WITH flattened_attrs AS (SELECT id, host, log_ts, level, status_code, payload_json, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, context['trace'] AS trace, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs) SELECT *, MIN(retry_count) OVER (PARTITION BY host) AS host_min_retry_count, LAST_VALUE(retry_count, TRUE) OVER (PARTITION BY tier ORDER BY status_code, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_retry_count, AVG(retry_count) OVER (PARTITION BY host ORDER BY status_code, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS retry_count_avg_3_prior, LEAD(status_code, 2) OVER (PARTITION BY tier, host ORDER BY retry_count, id) AS next_status_code FROM flattened_attrs
